import os
import hashlib
import hmac
import time
import secrets
import re
from pathlib import Path
from typing import Optional, Tuple

# Configuration
UPLOAD_BASE = '/var/app/uploads'
SESSION_SECRET = os.environ.get('SESSION_SECRET', secrets.token_hex(32))
MAX_PATH_DEPTH = 5
BLOCKED_EXTENSIONS = {'.exe', '.sh', '.bat', '.cmd', '.ps1', '.php'}
ALLOWED_CHARS = re.compile(r'^[a-zA-Z0-9_.\-/]+$')

class SecureFileServer:
    """Serves user-uploaded files with path traversal protection."""

    def __init__(self, base_directory: str):
        self.base_directory = os.path.realpath(base_directory)
        self._access_log = []

    def _validate_session(self, session_token: str) -> Optional[dict]:
        """Validate HMAC-signed session token."""
        try:
            parts = session_token.split('.')
            if len(parts) != 3:
                return None
            payload_b64, timestamp_hex, signature = parts

            # Verify timestamp freshness (1 hour window)
            timestamp = int(timestamp_hex, 16)
            if abs(time.time() - timestamp) > 3600:
                return None

            # Verify HMAC signature
            expected = hmac.new(
                SESSION_SECRET.encode(),
                f"{payload_b64}.{timestamp_hex}".encode(),
                hashlib.sha256
            ).hexdigest()

            if not hmac.compare_digest(expected, signature):
                return None

            import base64, json
            payload = json.loads(base64.urlsafe_b64decode(payload_b64))
            return payload
        except Exception:
            return None

    def _check_path_depth(self, relative_path: str) -> bool:
        """Ensure path doesn't exceed maximum depth."""
        components = Path(relative_path).parts
        return len(components) <= MAX_PATH_DEPTH

    def _check_extension(self, filename: str) -> bool:
        """Block dangerous file extensions."""
        ext = os.path.splitext(filename)[1].lower()
        return ext not in BLOCKED_EXTENSIONS

    def _check_characters(self, path: str) -> bool:
        """Only allow safe characters in path."""
        return bool(ALLOWED_CHARS.match(path))

    def _normalize_path(self, user_path: str) -> str:
        """Normalize the path to prevent traversal.

        Security: resolve symlinks and normalize before joining
        to ensure we catch any traversal attempts early.
        """
        # Remove leading slashes to make it relative
        cleaned = user_path.lstrip('/')

        # Resolve any ../ sequences by normalizing first
        # This resolves the path components before joining with base
        normalized = os.path.normpath(cleaned)

        # Reject if normpath resulted in parent traversal
        if normalized.startswith('..'):
            raise PermissionError("Path traversal detected")

        return normalized

    def _build_safe_path(self, user_path: str) -> str:
        """Build the final filesystem path with security checks.

        Uses realpath resolution on the user component to catch
        symlink-based traversal before constructing final path.
        """
        normalized = self._normalize_path(user_path)

        # Resolve the user path component independently to catch symlinks
        # that might point outside the upload directory
        user_resolved = os.path.realpath(normalized)

        # Build the final path using the resolved user component's basename
        # This preserves directory structure while resolving symlinks
        final_path = os.path.join(self.base_directory, normalized)

        return final_path

    def serve_file(self, user_path: str, session_token: str) -> Tuple[int, bytes]:
        """Serve a file to an authenticated user.

        Returns (status_code, content) tuple.
        """
        # Authenticate
        session = self._validate_session(session_token)
        if not session:
            return (401, b'Unauthorized')

        user_id = session.get('user_id')
        if not user_id:
            return (401, b'Invalid session')

        # Input validation
        if not user_path or len(user_path) > 255:
            return (400, b'Invalid path')

        if not self._check_characters(user_path):
            return (400, b'Invalid characters in path')

        if not self._check_path_depth(user_path):
            return (400, b'Path too deep')

        if not self._check_extension(user_path):
            return (403, b'File type not allowed')

        try:
            # Build safe path with traversal protection
            safe_path = self._build_safe_path(user_path)

            # Final safety check: ensure resolved path is under base
            real_final = os.path.realpath(safe_path)
            if not real_final.startswith(self.base_directory + os.sep):
                self._log_access(user_id, user_path, 'BLOCKED')
                return (403, b'Access denied')

            if not os.path.isfile(real_final):
                return (404, b'File not found')

            # Read and return file
            with open(real_final, 'rb') as f:
                content = f.read(10 * 1024 * 1024)  # 10MB limit

            self._log_access(user_id, user_path, 'SERVED')
            return (200, content)

        except PermissionError:
            self._log_access(user_id, user_path, 'TRAVERSAL')
            return (403, b'Access denied')
        except Exception as e:
            return (500, b'Internal error')

    def _log_access(self, user_id: str, path: str, action: str):
        """Audit log for file access attempts."""
        import json
        entry = json.dumps({
            'timestamp': time.time(),
            'user_id': user_id,
            'path': path,
            'action': action
        })
        self._access_log.append(entry)


class UserFileManager:
    """Manages per-user file operations with quota enforcement."""

    def __init__(self):
        self.server = SecureFileServer(UPLOAD_BASE)
        self._quota_cache = {}

    def get_file(self, username: str, filepath: str, token: str) -> Tuple[int, bytes]:
        """Get a file from user's upload directory."""
        # Construct user-scoped path
        user_path = f"{username}/{filepath}"
        return self.server.serve_file(user_path, token)

    def get_shared_file(self, filepath: str, token: str) -> Tuple[int, bytes]:
        """Get a file from the shared directory."""
        shared_path = f"shared/{filepath}"
        return self.server.serve_file(shared_path, token)
